<script setup lang="ts">
import {computed,ref,watch} from 'vue'
type Mode='clock'|'week'|'weather'|'outfit'
const mode=ref<Mode>('clock')
const activities=[{id:'get-up',en:'get up',zh:'起床',icon:'🌅'},{id:'breakfast',en:'have breakfast',zh:'吃早餐',icon:'🥣'},{id:'school',en:'have lessons',zh:'上课',icon:'📚'},{id:'sport',en:'play football',zh:'踢足球',icon:'⚽'},{id:'reading',en:'read stories',zh:'读故事',icon:'📖'},{id:'bed',en:'go to bed',zh:'上床睡觉',icon:'🌙'}] as const
const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']
const seasons=[{id:'spring',en:'spring',zh:'春天',icon:'🌷',weather:'warm',activity:'go boating'},{id:'summer',en:'summer',zh:'夏天',icon:'☀️',weather:'hot',activity:'go swimming'},{id:'autumn',en:'autumn',zh:'秋天',icon:'🍁',weather:'cool',activity:'fly a kite'},{id:'winter',en:'winter',zh:'冬天',icon:'❄️',weather:'cold',activity:'make a snowman'}] as const
const weatherOptions=[{id:'sunny',en:'sunny',icon:'☀️'},{id:'cloudy',en:'cloudy',icon:'☁️'},{id:'rainy',en:'rainy',icon:'🌧️'},{id:'windy',en:'windy',icon:'💨'},{id:'warm',en:'warm',icon:'🌤️'},{id:'hot',en:'hot',icon:'🔥'},{id:'cool',en:'cool',icon:'🍃'},{id:'cold',en:'cold',icon:'🧊'}] as const
const clothes=[{id:'cap',en:'cap',icon:'🧢',type:'head'},{id:'coat',en:'coat',icon:'🧥',type:'top'},{id:'shirt',en:'shirt',icon:'👕',type:'top'},{id:'dress',en:'dress',icon:'👗',type:'top'},{id:'skirt',en:'skirt',icon:'👗',type:'bottom'},{id:'trousers',en:'trousers',icon:'👖',type:'bottom'},{id:'shorts',en:'shorts',icon:'🩳',type:'bottom'}] as const
function stored<T>(key:string,fallback:T):T{try{const v=localStorage.getItem('lingualand-lab:'+key);return v?JSON.parse(v) as T:fallback}catch{return fallback}}
const hour=ref(7),minute=ref(0)
const clockTasks=[{h:7,m:0,en:"seven o'clock",context:'I get up at seven o’clock.'},{h:7,m:30,en:'seven thirty',context:'I have breakfast at seven thirty.'},{h:8,m:0,en:"eight o'clock",context:'I have lessons at eight o’clock.'},{h:9,m:30,en:'nine thirty',context:'I go to bed at nine thirty.'}]
const taskIndex=ref(0),clockResult=ref<'correct'|'wrong'|''>('')
const currentTask=computed(()=>clockTasks[taskIndex.value]!)
const timeLabel=computed(()=>String(hour.value).padStart(2,'0')+':'+String(minute.value).padStart(2,'0'))
const clockHandHour=computed(()=>((hour.value%12)+minute.value/60)*30)
const clockHandMinute=computed(()=>minute.value*6)
function adjustClock(kind:'hour'|'minute',step:number){if(kind==='hour')hour.value=(hour.value+step+12)%12||12;else minute.value=(minute.value+step+60)%60;clockResult.value=''}
function clockCheck(){clockResult.value=hour.value===currentTask.value.h&&minute.value===currentTask.value.m?'correct':'wrong'}
function nextClock(){taskIndex.value=(taskIndex.value+1)%clockTasks.length;clockResult.value=''}
const clockDial=ref<HTMLElement|null>(null)
function turnHand(event:PointerEvent){const box=clockDial.value?.getBoundingClientRect();if(!box)return;const x=event.clientX-(box.left+box.width/2),y=event.clientY-(box.top+box.height/2);const deg=(Math.atan2(x,-y)*180/Math.PI+360)%360;minute.value=Math.round(deg/30)*5%60;clockResult.value=''}
const week=ref<Record<string,string>>(stored('week',{})),selectedDay=ref('Monday'),selectedActivity=ref('get-up')
function assignDay(){week.value={...week.value,[selectedDay.value]:selectedActivity.value}}
watch(week,v=>localStorage.setItem('lingualand-lab:week',JSON.stringify(v)),{deep:true})
const selectedSeason=ref(0),selectedWeather=ref('warm'),selectedSeasonActivity=ref('go boating'),seasonResult=ref('')
const seasonActivities=['go boating','go swimming','fly a kite','make a snowman']
function checkSeason(){const s=seasons[selectedSeason.value]!;seasonResult.value=selectedWeather.value===s.weather&&selectedSeasonActivity.value===s.activity?'correct':'wrong'}
function nextSeason(){selectedSeason.value=(selectedSeason.value+1)%seasons.length;selectedWeather.value='';selectedSeasonActivity.value='';seasonResult.value=''}
const outfit=ref<Record<string,string>>(stored('outfit',{head:'',top:'',bottom:''})),outfitTask=ref(0),outfitResult=ref('')
const outfitTasks=[{en:'Wear a cap and a shirt.',zh:'戴帽子，穿衬衫',needs:['cap','shirt']},{en:'Wear a coat and trousers.',zh:'穿外套和长裤',needs:['coat','trousers']},{en:'Wear a dress.',zh:'穿连衣裙',needs:['dress']},{en:'Wear a shirt and shorts.',zh:'穿衬衫和短裤',needs:['shirt','shorts']}]
const chosenClothes=computed(()=>Object.values(outfit.value).filter(Boolean))
function chooseCloth(item:typeof clothes[number]){outfit.value={...outfit.value,[item.type]:outfit.value[item.type]===item.id?'':item.id};outfitResult.value=''}
watch(outfit,v=>localStorage.setItem('lingualand-lab:outfit',JSON.stringify(v)),{deep:true})
function checkOutfit(){const needed=outfitTasks[outfitTask.value]!.needs;outfitResult.value=chosenClothes.value.length===needed.length&&needed.every(x=>chosenClothes.value.includes(x))?'correct':'wrong'}
function nextOutfit(){outfitTask.value=(outfitTask.value+1)%outfitTasks.length;outfit.value={head:'',top:'',bottom:''};outfitResult.value=''}
function speak(text:string){if(!('speechSynthesis' in window))return;window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-US';utterance.rate=.82;window.speechSynthesis.speak(utterance)}
</script>
<template>
<section class="interactive-lab">
<header class="lab-heading"><span>✦ INTERACTIVE ENGLISH LAB</span><h2>四年级互动实验室</h2><p>用操作来学习英语：拨时钟、排日程、看天气、搭衣服。</p></header>
<nav class="lab-tabs" aria-label="选择交互练习">
<button v-for="item in [{id:'clock',icon:'🕒',name:'时间魔法'},{id:'week',icon:'📅',name:'一周计划'},{id:'weather',icon:'🌦️',name:'四季天气'},{id:'outfit',icon:'👕',name:'穿搭小屋'}] as const" :key="item.id" :class="{active:mode===item.id}" @click="mode=item.id">{{item.icon}} {{item.name}}</button>
</nav>
<div v-if="mode==='clock'" class="lab-panel"><div class="lab-section-title"><div><small>UNIT 2 · MY DAY</small><h3>时间魔法师</h3></div><button class="secondary" @click="speak(currentTask.en)">🔊 听时间</button></div><p class="lab-instruction">把时钟调到 <strong>{{currentTask.en}}</strong>，然后检查答案。</p>
<div class="lab-clock-layout"><div class="lab-clock">
<svg ref="clockDial" viewBox="0 0 300 300" role="img" aria-label="可点击的时钟表盘" @pointerdown="turnHand"><circle cx="150" cy="150" r="139" fill="#fffdf7" stroke="#a5c7b2" stroke-width="8"/><g v-for="n in 12" :key="n"><text :x="150+110*Math.sin(n*Math.PI/6)" :y="156-110*Math.cos(n*Math.PI/6)" text-anchor="middle" font-size="22" font-weight="800" fill="#375c4b">{{n}}</text></g><g :transform="'rotate('+clockHandHour+' 150 150)'"><line x1="150" y1="150" x2="150" y2="91" stroke="#385f52" stroke-width="11" stroke-linecap="round"/></g><g :transform="'rotate('+clockHandMinute+' 150 150)'"><line x1="150" y1="150" x2="150" y2="56" stroke="#e3a56c" stroke-width="7" stroke-linecap="round"/></g><circle cx="150" cy="150" r="10" fill="#385f52"/></svg></div>
<div class="lab-controls"><strong class="lab-time">{{timeLabel}}</strong><span>点击表盘设置分钟，或使用按钮精确调整</span><div class="lab-adjust"><span>时针</span><button @click="adjustClock('hour',-1)">−</button><b>{{hour}}</b><button @click="adjustClock('hour',1)">＋</button></div><div class="lab-adjust"><span>分针</span><button @click="adjustClock('minute',-5)">−</button><b>{{String(minute).padStart(2,'0')}}</b><button @click="adjustClock('minute',5)">＋</button></div><button class="primary" @click="clockCheck">检查时间 ✓</button><p v-if="clockResult" :class="['lab-feedback',clockResult]">{{clockResult==='correct'?'答对了！ '+currentTask.context:'还差一点，调整指针再试试。'}}</p><button class="secondary" @click="nextClock">下一道时间题 →</button></div></div></div>
<div v-else-if="mode==='week'" class="lab-panel"><div class="lab-section-title"><div><small>UNIT 3 · MY WEEK</small><h3>我的每周计划</h3></div><button class="secondary" @click="speak('What do you do on '+selectedDay+'?')">🔊 听问题</button></div><p class="lab-instruction">选择星期和活动，安排自己的每周计划。点击日程卡也能修改。</p><div class="lab-week-grid"><button v-for="day in days" :key="day" :class="['lab-day',{selected:selectedDay===day}]" @click="selectedDay=day"><strong>{{day}}</strong><span>{{activities.find(a=>a.id===week[day])?.icon||'＋'}}</span><small>{{activities.find(a=>a.id===week[day])?.en||'Add activity'}}</small></button></div><div class="lab-section-title"><h3>{{selectedDay}} · 选择活动</h3></div><div class="lab-choice-grid"><button v-for="a in activities" :key="a.id" :class="{chosen:selectedActivity===a.id}" @click="selectedActivity=a.id"><span>{{a.icon}}</span>{{a.en}}<small>{{a.zh}}</small></button></div><div class="lab-bottom"><button class="primary" @click="assignDay">安排到 {{selectedDay}}</button><button class="secondary" @click="speak('On '+selectedDay+', I '+(activities.find(a=>a.id===week[selectedDay])?.en||'play')+'.')">🔊 朗读日程</button></div><p class="lab-sentence">On {{selectedDay}}, I {{activities.find(a=>a.id===week[selectedDay])?.en||'…'}}.</p><p class="lab-note">日程自动保存在当前设备。</p></div>
<div v-else-if="mode==='weather'" class="lab-panel"><div class="lab-section-title"><div><small>UNIT 6 · WEATHER / UNIT 7 · SEASONS</small><h3>四季天气观察站</h3></div><button class="secondary" @click="speak('It is '+seasons[selectedSeason].en+'.')">🔊 听季节</button></div><div class="lab-season-card"><span>{{seasons[selectedSeason].icon}}</span><h3>{{seasons[selectedSeason].en}}</h3><p>{{seasons[selectedSeason].zh}} · 选择典型天气和适合的活动</p></div><h4>What's the weather like?</h4><div class="lab-choice-grid"><button v-for="w in weatherOptions" :key="w.id" :class="{chosen:selectedWeather===w.id}" @click="selectedWeather=w.id;seasonResult=''"><span>{{w.icon}}</span>{{w.en}}</button></div><h4>What can we do?</h4><div class="lab-choice-grid"><button v-for="a in seasonActivities" :key="a" :class="{chosen:selectedSeasonActivity===a}" @click="selectedSeasonActivity=a;seasonResult=''">{{a}}</button></div><div class="lab-bottom"><button class="primary" @click="checkSeason">检查匹配 ✓</button><button class="secondary" @click="nextSeason">下一个季节 →</button></div><p v-if="seasonResult" :class="['lab-feedback',seasonResult]">{{seasonResult==='correct'?'匹配成功！':'再想想这个季节的典型天气和活动。'}}</p><p class="lab-note">本练习使用典型季节场景，实际天气会随地区变化。</p></div>
<div v-else class="lab-panel"><div class="lab-section-title"><div><small>UNIT 8 · WHAT WE WEAR</small><h3>穿搭小屋</h3></div><button class="secondary" @click="speak(outfitTasks[outfitTask].en)">🔊 听穿搭任务</button></div><p class="lab-instruction">任务：<strong>{{outfitTasks[outfitTask].en}}</strong></p><div class="lab-outfit-layout"><div class="lab-character" aria-label="人物穿搭示意"><div class="lab-person-head">🙂<span>{{clothes.find(c=>c.id===outfit.head)?.icon||''}}</span></div><div class="lab-person-top">{{clothes.find(c=>c.id===outfit.top)?.icon||'👕'}}</div><div class="lab-person-bottom">{{clothes.find(c=>c.id===outfit.bottom)?.icon||'🦵'}}</div><p>{{chosenClothes.join(' + ')||'Choose clothes'}}</p></div><div class="lab-outfit-choices"><h4>选择衣服</h4><div class="lab-choice-grid"><button v-for="item in clothes" :key="item.id" :class="{chosen:outfit[item.type]===item.id}" @click="chooseCloth(item)"><span>{{item.icon}}</span>{{item.en}}</button></div></div></div><div class="lab-bottom"><button class="primary" @click="checkOutfit">完成穿搭 ✓</button><button class="secondary" @click="nextOutfit">下一个任务 →</button></div><p v-if="outfitResult" :class="['lab-feedback',outfitResult]">{{outfitResult==='correct'?'搭配正确！ Well done!':'检查一下服装是否符合英语任务。'}}</p><p class="lab-note">人物为简化示意，服装词汇与任务匹配才是学习重点。</p></div>
<footer class="lab-footer">基于译林版四年级上册（2025秋版）单元主题设计的原创交互练习，非教材原题。</footer>
</section>
</template>
<style scoped>
.interactive-lab{color:#315c4b}.lab-heading{margin:30px 0 24px}.lab-heading span,.lab-section-title small{font-size:11px;letter-spacing:2px;color:#77a38a;font-weight:900}.lab-heading h2{font-size:30px;margin:8px 0}.lab-heading p,.lab-instruction,.lab-note{color:#718d7d;line-height:1.8}.lab-tabs{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:22px}.lab-tabs button{padding:16px 8px;background:white;border:1px solid #dfebe2;border-radius:16px;color:#50745f;font-weight:800}.lab-tabs button.active{background:#dff3e6;border-color:#67b68e;color:#2d805b}.lab-panel{background:white;border:1px solid #e4eee5;border-radius:24px;padding:28px;box-shadow:0 10px 40px #427b5410}.lab-section-title{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:16px}.lab-section-title h3{margin:7px 0;font-size:22px}.lab-clock-layout{display:grid;grid-template-columns:minmax(220px,1fr) 1fr;align-items:center;gap:32px}.lab-clock{max-width:350px;margin:auto;width:100%;touch-action:none}.lab-clock svg{width:100%;cursor:crosshair}.lab-controls{display:flex;flex-direction:column;align-items:stretch;gap:13px}.lab-controls>span{color:#7c9987;font-size:12px}.lab-time{font-size:40px;letter-spacing:3px;color:#327f61}.lab-adjust{display:flex;align-items:center;gap:12px}.lab-adjust span{margin-right:auto}.lab-adjust button{border-radius:12px;background:#e8f4eb;padding:10px 16px;color:#377b5b;font-size:20px}.lab-adjust b{min-width:28px;text-align:center}.lab-week-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:9px;margin:20px 0 28px}.lab-day{min-height:120px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;border:1px solid #e2ebe3;border-radius:15px;background:#f7faf7;color:#4b6c5a}.lab-day.selected{border-color:#5cae81;background:#e8f7ed}.lab-day strong{font-size:12px}.lab-day span{font-size:30px}.lab-day small{font-size:11px;line-height:1.3}.lab-choice-grid{display:flex;gap:10px;flex-wrap:wrap}.lab-choice-grid button{min-width:110px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;padding:12px 16px;border:2px solid #e2ece4;background:#f8faf8;border-radius:15px;color:#3e6853;font-weight:800}.lab-choice-grid button.chosen{border-color:#50a87a;background:#e1f5e9}.lab-choice-grid button span{font-size:28px}.lab-choice-grid button small{font-size:11px;color:#8ca394}.lab-bottom{display:flex;flex-wrap:wrap;gap:12px;margin-top:25px}.lab-sentence{background:#f0f8f1;border-radius:14px;padding:18px;color:#367d5c;font-weight:800}.lab-season-card{text-align:center;background:linear-gradient(120deg,#e5f4e9,#fdf5e8);border-radius:20px;padding:24px}.lab-season-card span{font-size:60px}.lab-season-card h3{font-size:28px;margin:5px}.lab-season-card p{color:#76927e}.lab-panel h4{margin:22px 0 12px}.lab-feedback{padding:13px 16px;border-radius:12px;font-weight:800}.lab-feedback.correct{background:#e2f5e9;color:#278059}.lab-feedback.wrong{background:#fff2e5;color:#ae6b3c}.lab-outfit-layout{display:grid;grid-template-columns:210px 1fr;gap:30px}.lab-character{border-radius:22px;background:#e8f5ee;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:18px;min-height:290px}.lab-person-head{font-size:53px;position:relative}.lab-person-head span{position:absolute;top:-18px;left:8px;font-size:37px}.lab-person-top,.lab-person-bottom{font-size:60px;line-height:1.05}.lab-character p{font-size:12px;color:#6d8d79;text-align:center}.lab-footer{font-size:12px;color:#91a699;padding:24px 0;text-align:center}.lab-tabs button:focus-visible,.lab-panel button:focus-visible{outline:3px solid #e3ba72;outline-offset:3px}@media(max-width:850px){.lab-week-grid{grid-template-columns:repeat(4,1fr)}.lab-clock-layout{grid-template-columns:1fr}.lab-outfit-layout{grid-template-columns:1fr}}@media(max-width:550px){.lab-tabs{grid-template-columns:repeat(2,1fr)}.lab-panel{padding:17px}.lab-week-grid{grid-template-columns:repeat(2,1fr)}.lab-day{min-height:105px}.lab-heading h2{font-size:25px}.lab-outfit-layout{gap:10px}.lab-choice-grid button{min-width:95px}}
</style>